/* Same Bearer auth as the Chat Gateway. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, openai_error: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Aggregate the latest chat_executions rows into a compact stats summary.
   Kiranism (or any client) can consume this with a single authenticated GET. */
const rows = $input.all().map((i) => i.json).filter((r) => r && r.status);
const total = rows.length;
const ok = rows.filter((r) => r.status === 'success');
const failed = rows.filter((r) => r.status !== 'success');
const avgLatency = ok.length ? Math.round(ok.reduce((s, r) => s + (Number(r.latency_ms) || 0), 0) / ok.length) : 0;
const byModel = {};
const bySession = {};
const byClient = {};
for (const r of rows) {
  byModel[r.model || 'unknown'] = (byModel[r.model || 'unknown'] || 0) + 1;
  bySession[r.session_id || 'unknown'] = (bySession[r.session_id || 'unknown'] || 0) + 1;
  byClient[r.client || 'unknown'] = (byClient[r.client || 'unknown'] || 0) + 1;
}
const recent = rows.slice(0, 20).map((r) => ({
  execution_id: r.execution_id,
  session_id: r.session_id,
  model: r.model,
  client: r.client,
  status: r.status,
  error_code: r.error_code || null,
  error_message: r.error_message || null,
  latency_ms: r.latency_ms,
  total_tokens: r.total_tokens,
  prompt_tokens: r.prompt_tokens,
  completion_tokens: r.completion_tokens,
  created_at: r.createdAt,
}));
return [{ json: {
  window: { scanned: total },
  totals: {
    total,
    success: ok.length,
    error: failed.length,
    error_rate: total ? Number((failed.length / total).toFixed(3)) : 0,
  },
  avg_latency_ms: avgLatency,
  by_model: byModel,
  by_client: byClient,
  unique_sessions: Object.keys(bySession).length,
  recent,
} }];
